+function buildStagingPathspecs() {
+    var specs = [];
+    for (var i = 0; i < RUNTIME_ARTIFACT_PATHS.length; i++) {
+        specs.push('":!' + RUNTIME_ARTIFACT_PATHS[i] + '"');
+        specs.push('":!' + RUNTIME_ARTIFACT_PATHS[i] + '/**"');
